#
# Reference (host code in aten/src/ATen/native/sparse/cuda/SparseSemiStructuredOps.cu):
#   mask_cpu = dense_cpu != 0
#   packed   = dense_cpu.masked_select(mask_cpu).view(nrows, ncols/2)
#   metadata = per-node nibble words OR-ed from the FIRST TWO set slots of each
#              KSPARSE-wide group, reordered by cutlass ColumnMajorInterleaved<2>
# Geometry gate (all RuntimeError, in this order): rank 2, dtype in
# {fp16,bf16,int8,fp32}, rows % (32 for int16 meta / 16 for int32 meta) == 0,
# cols % PER_META == 0, and every group must keep exactly KSPARSE/2 slots.
#
# Two element orders are involved:
#   * `packed` is a masked_select: a LOGICAL row-major gathering of the retained
#     elements.  For a pattern that is valid in logical order the group layout is
#     static (packed[i,2g]/[i,2g+1]), which the fast kernel emits directly; when
#     the logical order is not group-valid but the input is still accepted (the
#     `transposed` layout fixture, whose group validity is decided in compact
#     order instead) a real per-row prefix-sum gather reproduces masked_select.
#   * the metadata loop walks mask_cpu.data_ptr() linearly.  The mask's buffer
#     keeps the tensor's own iteration order, which for a tensor whose dim0 is
#     the innermost strided dimension (`transposed`: strides (1, nrows)) is the
#     COMPACT order -- dim0 varying fastest -- so both the grouping and the
#     group-validity count run over that order.  Debug evidence: for that fixture
#     the reference accepts the input even though it is 2:4-invalid in logical
#     order, and its metadata equals a compact-order grouping exactly for
#     fp16/bf16/fp32/int8; for contiguous, sliced, dilated and expanded inputs
#     the logical grouping is the one that matches.
#
# Both outputs are compared with rtol=0/atol=0 and dtype equality, so retained
# values are moved with select trees (never an add) and -0.0 / NaN bit patterns
# survive verbatim.

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

_BLOCK_R = 32
_GATHER_R = 8
_GATHER_C = 512
_META_W = 128


@triton.jit
def _to_sss_kernel(
    dense_ptr,
    packed_ptr,
    meta_ptr,
    flag_ptr,
    nrows,
    ncols,
    meta_nrows,
    stride0,
    stride1,
    BLOCK_R: tl.constexpr,
    BLOCK_META: tl.constexpr,
    PER_META: tl.constexpr,
    KSPARSE: tl.constexpr,
    GROUP: tl.constexpr,  # reorder row group: 32 for int16 meta, 16 for int32
    INTERWEAVE: tl.constexpr,  # reorder row interleave: 4 for int16 meta, 2 for int32
    META_I32: tl.constexpr,
):
    """Fast path: logical row-major input with a logically valid pattern."""
    NG: tl.constexpr = PER_META // KSPARSE  # groups per metadata element
    BLOCK_C: tl.constexpr = BLOCK_META * PER_META
    NGRP: tl.constexpr = BLOCK_C // KSPARSE  # groups per row-block

    pid_r = tl.program_id(0)
    pid_c = tl.program_id(1)

    rows = pid_r * BLOCK_R + tl.arange(0, BLOCK_R)
    cols = pid_c * BLOCK_C + tl.arange(0, BLOCK_C)
    rmask = rows < nrows
    cmask = cols < ncols
    load_mask = rmask[:, None] & cmask[None, :]

    # Masked-out columns read as +0 so they count as pruned slots and can never
    # create a spurious validity failure.
    V = tl.load(
        dense_ptr + rows[:, None] * stride0 + cols[None, :] * stride1,
        mask=load_mask,
        other=0,
    )
    Vr = tl.reshape(V, (BLOCK_R, NGRP, KSPARSE))

    # A group participates in the validity check only when its whole metadata
    # element is inside the tensor (BLOCK_C is a multiple of PER_META and
    # ncols % PER_META == 0, so groups are never partially in range).
